__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),e.createFreshTrainingSession=function(t,h){let l=(0,s.createGameSession)(t);if(!o(t)||!h)return l;const c=n(h,0,h.rounds.length);for(let o=0;o<8&&n(l,0,l.rounds.length)===c;o+=1)l=(0,s.createGameSession)(t);return l},e.getGameIntroFocusBody=function(t){switch(t.id){case"master-or-reduce":return"Reduce each date before the ship loses altitude. Correct answers boost it back up; one miss or timeout ends the survival run.";case"cueseum":return"Pick a gallery, decode historical event dates, and unlock each exhibit as you play.";case"zodiac-boundary":return"Constellation Rush: slide between two zodiac gates to match the date. Every three correct crossings raise the pace from five seconds down to three. Each correct crossing adds a lasting constellation line.";case"trine-builder":return"Read the anchor animal and choose its two friendly trine partners. Keep building constellations until the one-minute timer ends.";case"dragon-boat-dash":return"Swipe or use the arrow keys to change lanes, hop and duck. Pass under your trine's arches to light your chain for a Trine Burst, and catch this year's lanterns for triple points. The pace doubles over the first 35 seconds; three crashes end the run. Earn one Cue Coin per 2,500 points.";case"digit-dive":return"Drag or use the arrow keys to move the diver; tap or press Space to fire a pearl line. Each hit reduces a bubble one step by adding its digits (47 \u2192 11), and single digits pop. Masters turn gold and rise to the vault: don't shoot them. Every fifth stage the Atlantean Warden grabs your masters and smashes them into the sand: dodge its hand, hit it to save the master, and shatter its core. Earn one Cue Coin per 1,000 points.";case"orbit-roll":return"Tilt the track and roll the Sun through the gate of the date's sign. A right gate boosts you; a wrong one drops you onto a slow stardust detour, and cusp days are narrow ledges. Jump the gaps, beat the clock for a medal, and get every gate right for a star. Finish a course to open the next, then roll the whole year in the Grand Orbit. Earn one Cue Coin per 500 points.";case"zodiac-slide":return"Tap a tile in line with the gap to slide it, and the whole run between them moves; or swipe a tile toward the gap. Rebuild the sign's picture: tiles that look the same can swap places. Three quick moves in a row that bring tiles closer to home start a streak for bonus points, and a hint shows the next best move for a few points at the end. Pick one of eight tiers, from Easy 3\xd73 to Mythic 10\xd710, and one of six picture styles. Each finished picture pays Cue Coins by tier, scaled by your points: Easy 2, Medium 4, Hard 8, Expert 15, Master 25, Champion 40, Legend 60, Mythic 90.";case"sun-breaker":return"Drag or move the mouse to slide the paddle; tap, click or press Space to launch. The Sun walks the year one day at a time and enters the next sign about every 20 seconds. Bricks dated in the Sun's sign are in season: they glow gold, score five times as much and drop power-ups (multi-ball, wide paddle, sunbeam). Cusp days, marked with a half-sun, flip the moment the Sun crosses. Chain gold bricks for a combo, clear the wall or outlast the clock, and keep your three suns in play. Earn one Cue Coin per 1,000 points.";case"sum-serpent":return"Steer the serpent into digit pellets. Each one is added to the number on its head, and past 9 the total reduces on the spot (8 + 8 = 16 \u2192 7). Land exactly on the target to bank it; the total carries on to the next target. Hit 11, 22 or 33 for Master Glow, and 20 becomes 11. Walls and your own tail end the run, and the clock stops it at 2:30. Earn one Cue Coin per 1,000 points.";case"star-garden":return"Plant seeds in the twelve sign beds. The garden grows in real time, fastest in the bed whose sign is in season, and daily watering raises the chance of rarer blooms; a flower left 30 days without care dies. Fill visitors' bouquet orders from the bed of their birthday's sign, and call the cusp when a birthday falls on one. Each bouquet earns 25 Cue Coins.";case"number-works":return"Swap any two tiles, tapping one and then the other, until every row adds up to a total that reduces to its target; from the third rung the columns count too. Tap a target to check its line, and finish within par for gold. Each board pays Cue Coins the first time it earns a medal: 15 for gold, 10 for silver, 5 for bronze, and a better medal later pays the difference.";case"tet-tiles":return"Clear a lantern-lit stack of carved tiles by pairing free tiles that belong together: the next animal in the cycle, a year and its animal, a birthday and its animal (before or after the Lunar New Year?), trines and enemy pairs. Tap a tile to read its rule card. A silver or gold opens the next board. Each finished board earns 3 Cue Coins, 5 when 80% of your pairs are clean and 10 when every pair is.";case"sapphire-shatter":return"Swap two neighbouring gemstones to line up three or more of a kind. Match four in a line to set a Cardinal sign, which clears its line; an L or T sets a Fixed sign, which blasts the gems around it; five sets a Mutable sign, which clears its element. Swap two signs together to play their aspect. Reach the level's points goal within its moves and every move left falls as a star. Earn one Cue Coin per 500 points.";case"trine-run":return"Run toward the castle. Tap to jump and tap again to double jump. Recruit missing trine teammates; duplicate teammates give +250 points. A hit or fall passes control to the next teammate.";default:return t.summary}};var t=r(d[0]),s=r(d[1]);function n(t,s,n){return t.rounds.slice(s,n).map(t=>`${t.prompt}:${t.options.map(t=>t.id).join("/")}`).join("|")}function o(s){const n=t.gameCatalog.find(t=>t.id===s);return!!n&&("Numerology"===n.category||"Western Astrology"===n.category||"Eastern Astrology"===n.category)}},989,[1005,973]);
